#!/usr/bin/env bash
# =============================================================================
# HERCOSSNUX PQC IP Core - Layer 2 delivery: packing codecs
#   rtl/pqc_codec_pkg.vhd  ByteEncode/ByteDecode      FIPS 203 Alg 5, 6
#                          SimpleBitPack/Unpack       FIPS 204 Alg 16, 18
#                          BitPack/BitUnpack          FIPS 204 Alg 17, 19
#                          HintBitPack/HintBitUnpack  FIPS 204 Alg 20, 21
#   verif/tb_codec.vhd     Layer 2 testbench with end-of-sim signature
#   verif/mutate_codec.sh  10 mutations, all must be killed (run separately)
#
# One parameterised little-endian bit-stream implementation covers every width
# (1, 4, 10, 12, 13, 20), so a packing bug cannot hide in one width while the
# others pass. HintBitUnpack runs six directed negative cases: a verifier that
# accepts a malformed hint encoding accepts forged signatures.
#
# Installs into: $HOME/vhdl_repo/IP_Cores/PQC/
# Expected single output line:
# PQC L2 CODEC PASS enc=28 sbp=12 bpk=21 hpk=6 huv=7 sig=5677e829e9c3593a
# =============================================================================
set -u
(
  set -e
  DEST="$HOME/vhdl_repo/IP_Cores/PQC"
  mkdir -p "$DEST/rtl" "$DEST/verif"
  base64 -d > "$DEST/rtl/pqc_codec_pkg.vhd" << 'B64EOF'
